<?php
// install4.php - Deploys: modules/admin/import.php + updated includes/header.php
$files = [
    'modules/admin/import.php' => '',
    'includes/header.php'      => '',
];

$base = __DIR__;
$ok = 0; $fail = 0; $msgs = [];

foreach ($files as $rel => $b64) {
    $target = $base . '/' . $rel;
    $dir    = dirname($target);
    if (!is_dir($dir)) {
        if (!mkdir($dir, 0755, true)) {
            $fail++;
            $msgs[] = "MKDIR FAILED: $dir";
            continue;
        }
    }
    $content = base64_decode($b64);
    if ($content === false) {
        $fail++;
        $msgs[] = "DECODE FAILED: $rel";
        continue;
    }
    if (file_put_contents($target, $content) === false) {
        $fail++;
        $msgs[] = "WRITE FAILED: $rel (dir writable=" . (is_writable($dir)?'yes':'no') . ")";
    } else {
        $ok++;
        $msgs[] = "OK: $rel";
    }
}

echo '<pre>';
echo "Base dir: $base\n";
echo "Results: $ok written, $fail failed\n\n";
foreach ($msgs as $m) { echo $m . "\n"; }
echo "\n";
if ($fail === 0) {
    echo "All files written successfully.\n";
    echo "Import CSV is now available at: /modules/admin/import.php\n";
    echo "DELETE this file (install4.php) after confirming.\n";
} else {
    echo "Some files failed to write. Check directory permissions.\n";
}
echo '</pre>';